/* ---- src/core/utils.js ---- */
/* Shared constants and helpers. */
window.Components = window.Components || {};

const TERMS = ['Winter', 'Spring', 'Summer', 'Fall'];
const MAIN_TERMS = ['Fall', 'Spring'];
const PRE_COLLEGE = 'PRE';
const UNASSIGNED = '__unassigned__';
const DEFAULT_AREAS = ['Major', 'Minor', 'Liberal Studies', 'Electives'];

const Utils = {
  esc(value) {
    return String(value ?? '').replace(/[&<>"']/g, (c) => (
      { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
    ));
  },

  uid(prefix) {
    return `${prefix}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  },

  clone(obj) {
    return JSON.parse(JSON.stringify(obj));
  },

  parseSemester(key) {
    const m = /^(Winter|Spring|Summer|Fall)\s+(\d{4})$/.exec(String(key || '').trim());
    return m ? { term: m[1], year: Number(m[2]) } : null;
  },

  /** Sortable index: Winter < Spring < Summer < Fall within a calendar year. */
  semesterOrder(key) {
    if (key === PRE_COLLEGE) return -Infinity;
    const p = Utils.parseSemester(key);
    return p ? p.year * 4 + TERMS.indexOf(p.term) : Infinity;
  },

  semesterFromOrder(order) {
    return `${TERMS[((order % 4) + 4) % 4]} ${Math.floor(order / 4)}`;
  },

  semesterLabel(key) {
    return key === PRE_COLLEGE ? 'Pre-College / AP' : key;
  },

  /**
   * Columns for a plan: pre-college column, then Fall/Spring (plus Winter/Summer
   * if enabled) for plan.years years. Semesters that hold courses but fall outside
   * the configured range (or a hidden term) are appended so nothing is lost.
   */
  planSemesters(plan) {
    const cols = [{ key: PRE_COLLEGE, label: Utils.semesterLabel(PRE_COLLEGE) }];
    const start = Utils.semesterOrder(plan.startSemester);
    if (Number.isFinite(start)) {
      const totalMain = Math.max(1, Number(plan.years) || 4) * 2;
      let main = 0;
      for (let o = start; main < totalMain; o++) {
        const term = TERMS[((o % 4) + 4) % 4];
        const isMain = MAIN_TERMS.includes(term);
        if (isMain) main++;
        const enabled = isMain || o === start
          || (term === 'Winter' && plan.showWinter)
          || (term === 'Summer' && plan.showSummer);
        if (enabled) {
          const key = Utils.semesterFromOrder(o);
          cols.push({ key, label: key, term });
        }
      }
    }
    const known = new Set(cols.map((c) => c.key));
    const extras = [...new Set(plan.courseList.map((e) => e.semester))]
      .filter((k) => !known.has(k))
      .sort((a, b) => Utils.semesterOrder(a) - Utils.semesterOrder(b));
    for (const key of extras) {
      cols.push({ key, label: key, term: Utils.parseSemester(key)?.term, extra: true });
    }
    return cols;
  },

  /** "A, B\nC" -> [["A","B"],["C"]]. Lines (or ';') separate sets; ',', '|' or ' or ' separate alternatives. */
  parseReqText(text) {
    return String(text || '')
      .split(/\n|;/)
      .map((line) => line.split(/,|\||\s+or\s+/i).map((s) => s.trim()).filter(Boolean))
      .filter((set) => set.length);
  },

  formatReqText(reqs) {
    return (reqs || []).map((set) => set.join(', ')).join('\n');
  },

  formatReqInline(reqs) {
    return (reqs || []).map((set) => (set.length > 1 ? `(${set.join(' or ')})` : set[0])).join(' and ');
  },

  formatCredits(n) {
    const v = Number(n) || 0;
    return Number.isInteger(v) ? String(v) : v.toFixed(1);
  },

  download(filename, data) {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 0);
  },

  slug(s) {
    return String(s || 'export').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'export';
  },

  /** Event target as an Element (drag events can target Text nodes). */
  targetEl(e) {
    const t = e.target;
    return t && t.nodeType === 1 ? t : t?.parentElement || document.body;
  },

  /** Clone a <template id="tpl-NAME"> into a fresh element. */
  template(name) {
    const tpl = document.getElementById(`tpl-${name}`);
    if (!tpl) throw new Error(`Missing template tpl-${name}`);
    return tpl.content.firstElementChild.cloneNode(true);
  },

  refs(root) {
    const out = {};
    root.querySelectorAll('[data-ref]').forEach((el) => { out[el.dataset.ref] = el; });
    return out;
  },

  toast(message, kind = 'info') {
    let host = document.querySelector('.toast-host');
    if (!host) {
      host = document.createElement('div');
      host.className = 'toast-host';
      document.body.appendChild(host);
    }
    const el = document.createElement('div');
    el.className = `toast toast-${kind}`;
    el.textContent = message;
    host.appendChild(el);
    setTimeout(() => el.classList.add('hide'), 2600);
    setTimeout(() => el.remove(), 3000);
  },
};

/* ---- src/core/bus.js ---- */
/* Tiny pub/sub used for cross-component requests (e.g. "open the course editor"). */
const Bus = (() => {
  const handlers = new Map();
  return {
    on(event, fn) {
      if (!handlers.has(event)) handlers.set(event, new Set());
      handlers.get(event).add(fn);
      return () => handlers.get(event).delete(fn);
    },
    emit(event, payload) {
      (handlers.get(event) || []).forEach((fn) => fn(payload));
    },
  };
})();

/* ---- src/core/validation.js ---- */
/* Pre-/co-requisite checks for a plan. Pre-college credits are treated as satisfied. */
const Validation = {
  /** @returns {Map<string, string[]>} courseId -> list of issues */
  validate(plan) {
    const issues = new Map();
    if (!plan) return issues;
    const when = new Map(plan.courseList.map((e) => [e.courseId, Utils.semesterOrder(e.semester)]));
    const roster = new Set(Store.university(plan.universityId)?.courses || []);
    const fmt = (set) => (set.length > 1 ? `one of ${set.join(', ')}` : set[0]);

    for (const entry of plan.courseList) {
      const msgs = [];
      const course = Store.course(entry.courseId);
      if (!course) {
        msgs.push('Course is not in the catalog');
      } else {
        if (!roster.has(course.id)) msgs.push('Course is not in this university\'s roster');
        if (entry.semester !== PRE_COLLEGE) {
          const mine = when.get(entry.courseId);
          for (const set of course.prerequisites || []) {
            if (!set.some((id) => when.has(id) && when.get(id) < mine)) {
              msgs.push(`Prerequisite: take ${fmt(set)} before ${entry.semester}`);
            }
          }
          for (const set of course.corequisites || []) {
            if (!set.some((id) => when.has(id) && when.get(id) <= mine)) {
              msgs.push(`Co-requisite: take ${fmt(set)} before or during ${entry.semester}`);
            }
          }
        }
      }
      if (msgs.length) issues.set(entry.courseId, msgs);
    }
    return issues;
  },
};

/* ---- src/core/store.js ---- */
/*
 * Application state, persisted to localStorage.
 *   courses       – shared course catalog (Course objects)
 *   universities  – rosters: { universityId, universityName, courses: [courseId] }
 *   plans         – CoursePlan objects
 *   ui            – current selection and view preferences
 */
const Store = (() => {
  const STORAGE_KEY = 'course-planner:v1';
  const listeners = new Set();
  let state = null;

  function normalizeCourse(c) {
    return {
      id: String(c.id).trim(),
      name: c.name || '',
      description: c.description || '',
      prerequisites: (c.prerequisites || []).map((s) => [...s]),
      corequisites: (c.corequisites || []).map((s) => [...s]),
      credits: Number(c.credits) || 0,
    };
  }

  function normalizePlan(p) {
    return {
      planId: p.planId || Utils.uid('plan'),
      planName: p.planName || 'Untitled plan',
      universityId: p.universityId || null,
      startSemester: p.startSemester || `Fall ${new Date().getFullYear()}`,
      years: Number(p.years) || 4,
      showWinter: !!p.showWinter,
      showSummer: !!p.showSummer,
      areasOfStudy: [...(p.areasOfStudy || DEFAULT_AREAS)],
      courseList: (p.courseList || []).map((e) => ({
        courseId: e.courseId,
        semester: e.semester || PRE_COLLEGE,
        areas: [...new Set(e.areas || [])],
      })),
    };
  }

  function normalizeUniversity(u) {
    return {
      universityId: String(u.universityId).trim(),
      universityName: u.universityName || u.universityId,
      courses: [...new Set((u.courses || []).map((c) => (typeof c === 'string' ? c : c.id)))],
    };
  }

  function emptyState() {
    return { courses: [], universities: [], plans: [], ui: { showNames: false, settingsOpen: false } };
  }

  function fixUi() {
    const ui = state.ui;
    if (!state.universities.some((u) => u.universityId === ui.universityId)) {
      ui.universityId = state.universities[0]?.universityId || null;
    }
    const plans = state.plans.filter((p) => p.universityId === ui.universityId);
    if (!plans.some((p) => p.planId === ui.planId)) ui.planId = plans[0]?.planId || null;
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (err) {
      console.warn('Could not persist state', err);
    }
  }

  function commit() {
    fixUi();
    save();
    listeners.forEach((fn) => fn(state));
  }

  function upsert(list, key, item) {
    const i = list.findIndex((x) => x[key] === item[key]);
    if (i >= 0) list[i] = item; else list.push(item);
  }

  /** Accepts a workspace, a single plan, a university roster, or a course array. */
  function mergeData(data) {
    const counts = { courses: 0, universities: 0, plans: 0 };
    const addCourses = (arr) => (arr || []).forEach((c) => {
      if (c && typeof c === 'object' && c.id) { upsert(state.courses, 'id', normalizeCourse(c)); counts.courses++; }
    });
    const addUniversity = (u) => {
      addCourses(u.courseCatalog);
      addCourses((u.courses || []).filter((c) => typeof c === 'object'));
      upsert(state.universities, 'universityId', normalizeUniversity(u));
      counts.universities++;
    };
    const addPlan = (p) => { upsert(state.plans, 'planId', normalizePlan(p)); counts.plans++; };

    if (Array.isArray(data)) {
      addCourses(data);
    } else if (data && (data.plans || data.universities || Array.isArray(data.courses) && !data.universityId)) {
      addCourses(data.courses);
      (data.universities || []).forEach(addUniversity);
      (data.plans || []).forEach(addPlan);
    } else if (data && data.planId && data.courseList) {
      addPlan(data);
    } else if (data && data.universityId) {
      addUniversity(data);
    } else {
      throw new Error('Unrecognized JSON format');
    }
    return counts;
  }

  function referencedCourseIds() {
    return new Set(state.universities.flatMap((u) => u.courses));
  }

  function pruneOrphanCourses() {
    const used = referencedCourseIds();
    state.courses = state.courses.filter((c) => used.has(c.id));
  }

  function plan() {
    return state.plans.find((p) => p.planId === state.ui.planId) || null;
  }

  function requirePlan() {
    const p = plan();
    if (!p) throw new Error('No plan selected');
    return p;
  }

  const api = {
    load() {
      let saved = null;
      try { saved = JSON.parse(localStorage.getItem(STORAGE_KEY)); } catch { /* ignore */ }
      state = emptyState();
      if (saved && Array.isArray(saved.courses)) {
        mergeData({ courses: saved.courses, universities: saved.universities, plans: saved.plans });
        state.ui = { ...state.ui, ...(saved.ui || {}) };
      } else {
        mergeData(Utils.clone(window.SAMPLE_DATA || {}));
      }
      fixUi();
      save();
    },

    subscribe(fn) { listeners.add(fn); return () => listeners.delete(fn); },
    get state() { return state; },

    course(id) { return state.courses.find((c) => c.id === id) || null; },
    university(id = state.ui.universityId) { return state.universities.find((u) => u.universityId === id) || null; },
    plan,
    plansForUniversity(id = state.ui.universityId) { return state.plans.filter((p) => p.universityId === id); },
    rosterCourses(id = state.ui.universityId) {
      const u = api.university(id);
      return u ? u.courses.map((cid) => api.course(cid)).filter(Boolean) : [];
    },

    /* ---------- UI ---------- */
    setUi(patch) { Object.assign(state.ui, patch); commit(); },
    selectUniversity(id) { state.ui.universityId = id; state.ui.planId = null; commit(); },
    selectPlan(id) { state.ui.planId = id; commit(); },

    /* ---------- Universities ---------- */
    saveUniversity({ universityId, universityName }, originalId = null) {
      const id = String(universityId || '').trim();
      if (!id) throw new Error('University ID is required');
      if (!String(universityName || '').trim()) throw new Error('University name is required');
      const clash = state.universities.find((u) => u.universityId === id);
      if (originalId) {
        const u = api.university(originalId);
        if (!u) throw new Error('University not found');
        if (clash && clash !== u) throw new Error(`University ID "${id}" already exists`);
        u.universityId = id;
        u.universityName = universityName.trim();
        state.plans.forEach((p) => { if (p.universityId === originalId) p.universityId = id; });
        if (state.ui.universityId === originalId) state.ui.universityId = id;
      } else {
        if (clash) throw new Error(`University ID "${id}" already exists`);
        state.universities.push({ universityId: id, universityName: universityName.trim(), courses: [] });
        state.ui.universityId = id;
        state.ui.planId = null;
      }
      commit();
    },

    deleteUniversity(id) {
      state.universities = state.universities.filter((u) => u.universityId !== id);
      state.plans = state.plans.filter((p) => p.universityId !== id);
      pruneOrphanCourses();
      commit();
    },

    /* ---------- Courses ---------- */
    saveCourse(input, originalId = null, universityId = state.ui.universityId) {
      const course = normalizeCourse({ ...input, id: String(input.id || '').trim() });
      if (!course.id) throw new Error('Course ID is required');
      if (!course.name.trim()) throw new Error('Course name is required');
      if (course.credits < 0) throw new Error('Credits cannot be negative');
      const uni = api.university(universityId);
      if (!uni) throw new Error('Select a university first');

      if (originalId && originalId !== course.id) {
        if (api.course(course.id)) throw new Error(`Course ID "${course.id}" already exists`);
        const rename = (x) => (x === originalId ? course.id : x);
        state.universities.forEach((u) => { u.courses = u.courses.map(rename); });
        state.courses.forEach((c) => {
          c.prerequisites = c.prerequisites.map((s) => s.map(rename));
          c.corequisites = c.corequisites.map((s) => s.map(rename));
        });
        state.plans.forEach((p) => p.courseList.forEach((e) => { e.courseId = rename(e.courseId); }));
        state.courses = state.courses.filter((c) => c.id !== originalId);
      } else if (!originalId && uni.courses.includes(course.id)) {
        throw new Error(`Course "${course.id}" is already in this university's roster`);
      }
      upsert(state.courses, 'id', course);
      if (!uni.courses.includes(course.id)) uni.courses.push(course.id);
      commit();
      return course;
    },

    deleteCourse(id, universityId = state.ui.universityId) {
      const uni = api.university(universityId);
      if (uni) uni.courses = uni.courses.filter((c) => c !== id);
      state.plans.forEach((p) => {
        if (p.universityId === universityId) p.courseList = p.courseList.filter((e) => e.courseId !== id);
      });
      pruneOrphanCourses();
      commit();
    },

    /* ---------- Plans ---------- */
    createPlan({ planName, startSemester, areasOfStudy } = {}) {
      if (!state.ui.universityId) throw new Error('Create a university first');
      const p = normalizePlan({
        planName: planName || 'New Plan',
        universityId: state.ui.universityId,
        startSemester,
        areasOfStudy: areasOfStudy || DEFAULT_AREAS,
      });
      state.plans.push(p);
      state.ui.planId = p.planId;
      state.ui.settingsOpen = true;
      commit();
      return p;
    },

    duplicatePlan() {
      const src = requirePlan();
      const copy = normalizePlan({ ...Utils.clone(src), planId: null, planName: `${src.planName} (copy)` });
      state.plans.push(copy);
      state.ui.planId = copy.planId;
      commit();
    },

    deletePlan(id = state.ui.planId) {
      state.plans = state.plans.filter((p) => p.planId !== id);
      commit();
    },

    updatePlan(patch) {
      Object.assign(requirePlan(), patch);
      commit();
    },

    addArea(name) {
      const p = requirePlan();
      const n = String(name || '').trim();
      if (!n) throw new Error('Area name is required');
      if (p.areasOfStudy.includes(n)) throw new Error(`Area "${n}" already exists`);
      p.areasOfStudy.push(n);
      commit();
    },

    renameArea(oldName, newName) {
      const p = requirePlan();
      const n = String(newName || '').trim();
      if (!n || n === oldName) return;
      if (p.areasOfStudy.includes(n)) throw new Error(`Area "${n}" already exists`);
      p.areasOfStudy = p.areasOfStudy.map((a) => (a === oldName ? n : a));
      p.courseList.forEach((e) => { e.areas = e.areas.map((a) => (a === oldName ? n : a)); });
      if (state.ui.highlightArea === oldName) state.ui.highlightArea = n;
      commit();
    },

    deleteArea(name) {
      const p = requirePlan();
      p.areasOfStudy = p.areasOfStudy.filter((a) => a !== name);
      p.courseList.forEach((e) => { e.areas = e.areas.filter((a) => a !== name); });
      if (state.ui.highlightArea === name) state.ui.highlightArea = null;
      commit();
    },

    moveArea(name, delta) {
      const p = requirePlan();
      const i = p.areasOfStudy.indexOf(name);
      const j = i + delta;
      if (i < 0 || j < 0 || j >= p.areasOfStudy.length) return;
      [p.areasOfStudy[i], p.areasOfStudy[j]] = [p.areasOfStudy[j], p.areasOfStudy[i]];
      commit();
    },

    /* ---------- Plan entries ---------- */
    entry(courseId) {
      return plan()?.courseList.find((e) => e.courseId === courseId) || null;
    },

    saveEntry({ courseId, semester, areas, primaryArea = null }) {
      const p = requirePlan();
      if (!api.course(courseId)) throw new Error(`Unknown course "${courseId}"`);
      let cleanAreas = [...new Set(areas || [])].filter((a) => p.areasOfStudy.includes(a));
      const existing = p.courseList.find((e) => e.courseId === courseId);
      if (existing) {
        // Preserve the existing order (the first area is the row the course is shown in).
        const kept = existing.areas.filter((a) => cleanAreas.includes(a));
        cleanAreas = [...kept, ...cleanAreas.filter((a) => !kept.includes(a))];
      }
      if (primaryArea && cleanAreas.includes(primaryArea)) {
        cleanAreas = [primaryArea, ...cleanAreas.filter((a) => a !== primaryArea)];
      }
      if (existing) {
        existing.semester = semester;
        existing.areas = cleanAreas;
      } else {
        p.courseList.push({ courseId, semester, areas: cleanAreas });
      }
      commit();
    },

    removeEntry(courseId) {
      const p = requirePlan();
      p.courseList = p.courseList.filter((e) => e.courseId !== courseId);
      commit();
    },

    /**
     * Drag & drop: move to a semester. Dropping on another row makes that area the
     * primary (displayed) area: kept if already assigned, otherwise it replaces fromArea.
     */
    dropCourse(courseId, semester, toArea, fromArea = null) {
      const p = requirePlan();
      if (!api.course(courseId)) throw new Error(`Unknown course "${courseId}"`);
      let e = p.courseList.find((x) => x.courseId === courseId);
      if (!e) {
        e = { courseId, semester, areas: [] };
        p.courseList.push(e);
      }
      e.semester = semester;
      if (toArea && toArea !== fromArea) {
        if (toArea === UNASSIGNED) {
          e.areas = e.areas.filter((a) => !p.areasOfStudy.includes(a));
        } else {
          const rest = e.areas.filter((a) => a !== toArea && !(a === fromArea && !e.areas.includes(toArea)));
          e.areas = [toArea, ...rest];
        }
      }
      commit();
    },

    /* ---------- Import / export ---------- */
    importData(data) {
      const counts = mergeData(data);
      if (data && data.planId && state.plans.some((p) => p.planId === data.planId)) {
        state.ui.universityId = data.universityId;
        state.ui.planId = data.planId;
      } else if (data && data.universityId && !data.planId) {
        state.ui.universityId = data.universityId;
      }
      commit();
      return counts;
    },

    exportWorkspace() {
      const { courses, universities, plans } = Utils.clone(state);
      return { courses, universities, plans };
    },

    exportUniversity(id = state.ui.universityId) {
      const u = api.university(id);
      if (!u) throw new Error('No university selected');
      return { ...Utils.clone(u), courseCatalog: Utils.clone(api.rosterCourses(id)) };
    },

    exportPlan() {
      return Utils.clone(requirePlan());
    },

    resetToSample() {
      const ui = { showNames: state.ui.showNames };
      state = emptyState();
      Object.assign(state.ui, ui);
      mergeData(Utils.clone(window.SAMPLE_DATA || {}));
      commit();
    },
  };
  return api;
})();

/* ---- src/components/app-header/app-header.js ---- */
/* Top bar: university / plan selection, plan CRUD, import / export. */
window.Components['app-header'] = class AppHeader {
  constructor(host) {
    this.el = Utils.template('app-header');
    host.replaceWith(this.el);
    this.refs = Utils.refs(this.el);

    this.refs.university.addEventListener('change', (e) => Store.selectUniversity(e.target.value));
    this.refs.plan.addEventListener('change', (e) => Store.selectPlan(e.target.value));
    this.refs.file.addEventListener('change', (e) => this.importFile(e.target.files[0]));
    this.el.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-action]');
      if (btn) this.onAction(btn.dataset.action);
    });
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.hdr-menu')) this.refs.exportMenu.hidden = true;
    });
  }

  onAction(action) {
    try {
      switch (action) {
        case 'manage-universities': Bus.emit('manage-universities'); break;
        case 'new-plan': {
          if (!Store.university()) { Utils.toast('Create a university first', 'error'); Bus.emit('manage-universities'); break; }
          const name = prompt('Name for the new plan:', 'New Plan');
          if (name !== null) Store.createPlan({ planName: name.trim() || 'New Plan' });
          break;
        }
        case 'duplicate-plan': Store.duplicatePlan(); Utils.toast('Plan duplicated', 'success'); break;
        case 'delete-plan': {
          const p = Store.plan();
          if (p && confirm(`Delete plan "${p.planName}"? This cannot be undone.`)) Store.deletePlan(p.planId);
          break;
        }
        case 'import': this.refs.file.value = ''; this.refs.file.click(); break;
        case 'toggle-export': this.refs.exportMenu.hidden = !this.refs.exportMenu.hidden; break;
        case 'export-plan': {
          const p = Store.exportPlan();
          Utils.download(`plan-${Utils.slug(p.planName)}.json`, p);
          break;
        }
        case 'export-university': {
          const u = Store.exportUniversity();
          Utils.download(`university-${Utils.slug(u.universityId)}.json`, u);
          break;
        }
        case 'export-workspace': Utils.download('course-planner-workspace.json', Store.exportWorkspace()); break;
        case 'reset':
          if (confirm('Replace ALL local data with the sample data? Export first if you want to keep your changes.')) {
            Store.resetToSample();
            Utils.toast('Sample data restored', 'success');
          }
          break;
        default: break;
      }
      if (action.startsWith('export-')) this.refs.exportMenu.hidden = true;
    } catch (err) {
      Utils.toast(err.message, 'error');
    }
  }

  async importFile(file) {
    if (!file) return;
    try {
      const counts = Store.importData(JSON.parse(await file.text()));
      const parts = Object.entries(counts).filter(([, n]) => n).map(([k, n]) => `${n} ${k}`);
      Utils.toast(`Imported ${parts.join(', ') || 'nothing'}`, 'success');
    } catch (err) {
      Utils.toast(`Import failed: ${err.message}`, 'error');
    }
  }

  render() {
    const { state } = Store;
    const { university, plan, duplicate } = this.refs;
    university.innerHTML = state.universities.length
      ? state.universities.map((u) => `<option value="${Utils.esc(u.universityId)}">${Utils.esc(u.universityName)}</option>`).join('')
      : '<option value="">— none —</option>';
    university.value = state.ui.universityId || '';

    const plans = Store.plansForUniversity();
    plan.innerHTML = plans.length
      ? plans.map((p) => `<option value="${Utils.esc(p.planId)}">${Utils.esc(p.planName)}</option>`).join('')
      : '<option value="">— no plans —</option>';
    plan.value = state.ui.planId || '';
    plan.disabled = !plans.length;
    duplicate.disabled = !Store.plan();
    this.refs.delete.disabled = !Store.plan();
  }
};

/* ---- src/components/course-catalog/course-catalog.js ---- */
/* Sidebar list of the selected university's roster, with search, CRUD, and drag source. */
window.Components['course-catalog'] = class CourseCatalog {
  constructor(host) {
    this.el = Utils.template('course-catalog');
    host.appendChild(this.el);
    this.refs = Utils.refs(this.el);

    this.refs.search.addEventListener('input', () => this.renderList());
    this.refs.filter.addEventListener('change', () => this.renderList());
    this.el.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-action]');
      if (!btn) return;
      const id = btn.closest('[data-course]')?.dataset.course;
      switch (btn.dataset.action) {
        case 'new-course': Bus.emit('edit-course', {}); break;
        case 'edit-course': Bus.emit('edit-course', { courseId: id }); break;
        case 'plan-course': Bus.emit('edit-plan-entry', { courseId: id }); break;
        case 'delete-course': this.deleteCourse(id); break;
        default: break;
      }
    });
    this.refs.list.addEventListener('dragstart', (e) => {
      const item = Utils.targetEl(e).closest('[data-course]');
      if (!item) return;
      e.dataTransfer.effectAllowed = 'copyMove';
      e.dataTransfer.setData('text/plain', JSON.stringify({ courseId: item.dataset.course }));
      document.body.classList.add('is-dragging');
    });
    this.refs.list.addEventListener('dragend', () => document.body.classList.remove('is-dragging'));
  }

  deleteCourse(id) {
    const plans = Store.plansForUniversity().filter((p) => p.courseList.some((e) => e.courseId === id));
    const note = plans.length ? `\n\nIt will also be removed from ${plans.length} plan(s): ${plans.map((p) => p.planName).join(', ')}.` : '';
    if (confirm(`Delete course ${id} from ${Store.university().universityName}?${note}`)) {
      Store.deleteCourse(id);
      Utils.toast(`Deleted ${id}`, 'success');
    }
  }

  render() {
    const uni = Store.university();
    this.refs.newBtn.disabled = !uni;
    this.refs.count.textContent = uni ? `(${uni.courses.length})` : '';
    this.renderList();
  }

  renderList() {
    const uni = Store.university();
    const list = this.refs.list;
    if (!uni) { list.innerHTML = '<li class="cc-empty muted">Select or create a university.</li>'; return; }

    const plan = Store.plan();
    const issues = Validation.validate(plan);
    const q = this.refs.search.value.trim().toLowerCase();
    const filter = this.refs.filter.value;
    const courses = Store.rosterCourses()
      .slice()
      .sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }))
      .filter((c) => !q || `${c.id} ${c.name} ${c.description}`.toLowerCase().includes(q))
      .filter((c) => {
        const entry = plan?.courseList.find((e) => e.courseId === c.id);
        if (filter === 'planned') return !!entry;
        if (filter === 'unplanned') return !entry;
        if (filter === 'issues') return issues.has(c.id);
        return true;
      });

    if (!courses.length) {
      list.innerHTML = `<li class="cc-empty muted">${uni.courses.length ? 'No matching courses.' : 'No courses yet — click “+ New”.'}</li>`;
      return;
    }
    list.innerHTML = courses.map((c) => {
      const entry = plan?.courseList.find((e) => e.courseId === c.id);
      const reqs = [
        c.prerequisites.length ? `<div><b>Pre:</b> ${Utils.esc(Utils.formatReqInline(c.prerequisites))}</div>` : '',
        c.corequisites.length ? `<div><b>Co:</b> ${Utils.esc(Utils.formatReqInline(c.corequisites))}</div>` : '',
      ].join('');
      return `
        <li class="cc-item ${entry ? 'cc-planned' : ''} ${issues.has(c.id) ? 'cc-issue' : ''}" draggable="${plan ? 'true' : 'false'}"
            data-course="${Utils.esc(c.id)}" title="${Utils.esc(c.description || c.name)}">
          <div class="cc-row">
            <span class="cc-id">${Utils.esc(c.id)}</span>
            <span class="cc-cr">${Utils.formatCredits(c.credits)} cr</span>
          </div>
          <div class="cc-name">${Utils.esc(c.name)}</div>
          ${reqs ? `<div class="cc-reqs">${reqs}</div>` : ''}
          <div class="cc-row cc-actions">
            ${entry
              ? `<span class="cc-badge" title="${Utils.esc(entry.areas.join(', '))}">${issues.has(c.id) ? '⚠ ' : ''}${Utils.esc(Utils.semesterLabel(entry.semester))}</span>`
              : '<span class="muted cc-unplanned">Not planned</span>'}
            <span class="cc-btns">
              ${plan ? `<button class="icon" data-action="plan-course" title="${entry ? 'Edit in plan' : 'Add to plan'}">${entry ? '📅' : '➕'}</button>` : ''}
              <button class="icon" data-action="edit-course" title="Edit course">✎</button>
              <button class="icon" data-action="delete-course" title="Delete course">🗑</button>
            </span>
          </div>
        </li>`;
    }).join('');
  }
};

/* ---- src/components/course-editor/course-editor.js ---- */
/* Modal for creating / editing a course in the current university's roster. */
window.Components['course-editor'] = class CourseEditor {
  constructor(host) {
    this.el = Utils.template('course-editor');
    host.replaceWith(this.el);
    this.refs = Utils.refs(this.el);
    this.originalId = null;

    Bus.on('edit-course', ({ courseId, presetId } = {}) => this.open(courseId, presetId));
    this.el.addEventListener('click', (e) => {
      if (e.target.closest('[data-action="cancel"]')) this.el.close();
    });
    this.refs.form.addEventListener('submit', (e) => { e.preventDefault(); this.save(); });
    ['prerequisites', 'corequisites'].forEach((k) => this.refs[k].addEventListener('input', () => this.checkUnknown()));
  }

  open(courseId = null, presetId = '') {
    if (!Store.university()) { Utils.toast('Create a university first', 'error'); return; }
    const c = courseId ? Store.course(courseId) : null;
    this.originalId = c ? c.id : null;
    const r = this.refs;
    r.title.textContent = c ? `Edit course ${c.id}` : `New course · ${Store.university().universityName}`;
    r.id.value = c?.id || presetId || '';
    r.name.value = c?.name || '';
    r.credits.value = c ? c.credits : 3;
    r.description.value = c?.description || '';
    r.prerequisites.value = Utils.formatReqText(c?.prerequisites);
    r.corequisites.value = Utils.formatReqText(c?.corequisites);
    r.error.textContent = '';
    this.checkUnknown();
    this.el.showModal();
    (c ? r.name : r.id).focus();
  }

  checkUnknown() {
    const ids = [
      ...Utils.parseReqText(this.refs.prerequisites.value),
      ...Utils.parseReqText(this.refs.corequisites.value),
    ].flat();
    const unknown = [...new Set(ids)].filter((id) => !Store.course(id));
    this.refs.unknown.textContent = unknown.length ? `Note: not in catalog yet — ${unknown.join(', ')}` : '';
  }

  save() {
    const r = this.refs;
    try {
      const course = Store.saveCourse({
        id: r.id.value,
        name: r.name.value,
        credits: parseFloat(r.credits.value),
        description: r.description.value.trim(),
        prerequisites: Utils.parseReqText(r.prerequisites.value),
        corequisites: Utils.parseReqText(r.corequisites.value),
      }, this.originalId);
      this.el.close();
      Utils.toast(`Saved ${course.id}`, 'success');
    } catch (err) {
      r.error.textContent = err.message;
    }
  }
};

/* ---- src/components/plan-course-dialog/plan-course-dialog.js ---- */
/* Modal for adding a course to the plan or editing its semester / areas. */
window.Components['plan-course-dialog'] = class PlanCourseDialog {
  constructor(host) {
    this.el = Utils.template('plan-course-dialog');
    host.replaceWith(this.el);
    this.refs = Utils.refs(this.el);

    Bus.on('edit-plan-entry', (opts) => this.open(opts || {}));
    this.refs.form.addEventListener('submit', (e) => { e.preventDefault(); this.save(); });
    this.refs.course.addEventListener('input', () => this.onCourseChange());
    this.refs.areas.addEventListener('change', () => this.renderPrimary());
    this.el.addEventListener('click', (e) => {
      const action = e.target.closest('[data-action]')?.dataset.action;
      if (action === 'cancel') this.el.close();
      if (action === 'remove') this.remove();
      if (action === 'edit-course') {
        const id = this.refs.course.value.trim();
        this.el.close();
        Bus.emit('edit-course', Store.course(id) ? { courseId: id } : { presetId: id });
      }
    });
  }

  open({ courseId = null, semester = null, area = null }) {
    const plan = Store.plan();
    if (!plan) { Utils.toast('Create or select a plan first', 'error'); return; }
    const r = this.refs;
    const entry = courseId ? Store.entry(courseId) : null;
    this.editing = !!entry;

    r.title.textContent = entry ? `Edit ${courseId} in plan` : 'Add course to plan';
    r.course.value = courseId || '';
    r.course.readOnly = !!entry;
    r.options.innerHTML = Store.rosterCourses()
      .filter((c) => !plan.courseList.some((e) => e.courseId === c.id))
      .map((c) => `<option value="${Utils.esc(c.id)}">${Utils.esc(c.name)} (${Utils.formatCredits(c.credits)} cr)</option>`)
      .join('');

    const cols = Utils.planSemesters(plan);
    const sem = entry?.semester || semester || cols[1]?.key || PRE_COLLEGE;
    r.semester.innerHTML = cols.map((c) => `<option value="${Utils.esc(c.key)}">${Utils.esc(c.label)}</option>`).join('');
    r.semester.value = sem;

    const selected = new Set(entry ? entry.areas : area ? [area] : []);
    this.primary = entry?.areas.find((a) => plan.areasOfStudy.includes(a)) || area || null;
    r.areas.innerHTML = plan.areasOfStudy.map((a) => `
      <label><input type="checkbox" value="${Utils.esc(a)}" ${selected.has(a) ? 'checked' : ''}> ${Utils.esc(a)}</label>`).join('')
      || '<span class="muted">No areas defined — add some in Plan settings.</span>';
    r.primary.innerHTML = '';
    this.renderPrimary();

    r.error.textContent = '';
    this.onCourseChange();
    this.el.showModal();
    if (!entry) r.course.focus();
  }

  onCourseChange() {
    const r = this.refs;
    const id = r.course.value.trim();
    const c = Store.course(id);
    const entry = Store.entry(id);
    r.remove.hidden = !this.editing;
    r.editCourse.textContent = c ? 'Edit course…' : 'Create course…';
    if (!id) { r.info.innerHTML = ''; return; }
    if (!c) { r.info.innerHTML = '<span class="muted">Unknown course ID — use “Create course…” to add it to the roster.</span>'; return; }
    const issues = Validation.validate(Store.plan()).get(id) || [];
    r.info.innerHTML = `
      <div><b>${Utils.esc(c.name)}</b> · ${Utils.formatCredits(c.credits)} credits</div>
      ${c.description ? `<div class="muted">${Utils.esc(c.description)}</div>` : ''}
      ${c.prerequisites.length ? `<div><b>Pre-reqs:</b> ${Utils.esc(Utils.formatReqInline(c.prerequisites))}</div>` : ''}
      ${c.corequisites.length ? `<div><b>Co-reqs:</b> ${Utils.esc(Utils.formatReqInline(c.corequisites))}</div>` : ''}
      ${!this.editing && entry ? `<div class="pcd-note">Already planned in ${Utils.esc(Utils.semesterLabel(entry.semester))} — saving will move it.</div>` : ''}
      ${issues.map((m) => `<div class="pcd-warn">⚠ ${Utils.esc(m)}</div>`).join('')}`;
  }

  checkedAreas() {
    return [...this.refs.areas.querySelectorAll('input:checked')].map((i) => i.value);
  }

  renderPrimary() {
    const r = this.refs;
    const checked = this.checkedAreas();
    if (r.primary.options.length) this.primary = r.primary.value;
    if (!checked.includes(this.primary)) this.primary = checked[0] || null;
    r.primaryField.hidden = checked.length < 2;
    r.primary.innerHTML = checked.map((a) => `<option value="${Utils.esc(a)}">${Utils.esc(a)}</option>`).join('');
    if (this.primary) r.primary.value = this.primary;
  }

  save() {
    const r = this.refs;
    try {
      const courseId = r.course.value.trim();
      if (!courseId) throw new Error('Choose a course');
      const areas = this.checkedAreas();
      Store.saveEntry({ courseId, semester: r.semester.value, areas, primaryArea: r.primary.value || null });
      this.el.close();
      const issues = Validation.validate(Store.plan()).get(courseId);
      if (issues) Utils.toast(`${courseId}: ${issues[0]}`, 'error');
    } catch (err) {
      r.error.textContent = err.message;
    }
  }

  remove() {
    const id = this.refs.course.value.trim();
    Store.removeEntry(id);
    this.el.close();
    Utils.toast(`Removed ${id} from plan`, 'success');
  }
};

/* ---- src/components/plan-grid/plan-grid.js ---- */
/* Semester (columns) × area-of-study (rows) grid with live totals and drag & drop. */
window.Components['plan-grid'] = class PlanGrid {
  constructor(host) {
    this.el = Utils.template('plan-grid');
    host.replaceWith(this.el);
    this.refs = Utils.refs(this.el);
    this.empty = document.createElement('div');
    this.empty.className = 'empty';
    this.el.before(this.empty);

    this.refs.showNames.addEventListener('change', (e) => Store.setUi({ showNames: e.target.checked }));
    this.el.addEventListener('click', (e) => this.onClick(e));
    this.empty.addEventListener('click', (e) => {
      const action = e.target.closest('[data-action]')?.dataset.action;
      if (action === 'manage-universities') Bus.emit('manage-universities');
      if (action === 'new-plan') this.safe(() => Store.createPlan({ planName: 'New Plan' }));
    });
    this.bindDragAndDrop();
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && Store.state.ui.highlightArea && !document.querySelector('dialog[open]')) {
        Store.setUi({ highlightArea: null });
      }
    });
  }

  safe(fn) {
    try { fn(); } catch (err) { Utils.toast(err.message, 'error'); }
  }

  onClick(e) {
    const target = e.target.closest('[data-action]');
    if (!target) return;
    const chip = e.target.closest('.chip');
    const cell = e.target.closest('td.pg-cell');
    switch (target.dataset.action) {
      case 'add-course': Bus.emit('edit-plan-entry', {}); break;
      case 'remove-chip':
        e.stopPropagation();
        this.safe(() => Store.removeEntry(chip.dataset.course));
        break;
      case 'highlight-area': {
        const area = target.dataset.area;
        Store.setUi({ highlightArea: Store.state.ui.highlightArea === area ? null : area });
        break;
      }
      case 'clear-highlight': Store.setUi({ highlightArea: null }); break;
      case 'edit-chip': Bus.emit('edit-plan-entry', { courseId: chip.dataset.course }); break;
      case 'add-in-cell':
        Bus.emit('edit-plan-entry', { semester: cell.dataset.sem, area: cell.dataset.area === UNASSIGNED ? null : cell.dataset.area });
        break;
      default: break;
    }
  }

  bindDragAndDrop() {
    const table = this.refs.table;
    table.addEventListener('dragstart', (e) => {
      const chip = Utils.targetEl(e).closest('.chip');
      if (!chip) return;
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', JSON.stringify({ courseId: chip.dataset.course, fromArea: chip.dataset.area }));
      chip.classList.add('dragging');
      document.body.classList.add('is-dragging');
    });
    table.addEventListener('dragend', (e) => {
      Utils.targetEl(e).closest('.chip')?.classList.remove('dragging');
      document.body.classList.remove('is-dragging');
      table.querySelectorAll('.drop-over').forEach((c) => c.classList.remove('drop-over'));
    });
    table.addEventListener('dragover', (e) => {
      const cell = Utils.targetEl(e).closest('td.pg-cell');
      if (!cell) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      if (!cell.classList.contains('drop-over')) {
        table.querySelectorAll('.drop-over').forEach((c) => c.classList.remove('drop-over'));
        cell.classList.add('drop-over');
      }
    });
    table.addEventListener('dragleave', (e) => {
      const cell = Utils.targetEl(e).closest('td.pg-cell');
      if (cell && !cell.contains(e.relatedTarget)) cell.classList.remove('drop-over');
    });
    table.addEventListener('drop', (e) => {
      const cell = Utils.targetEl(e).closest('td.pg-cell');
      if (!cell) return;
      e.preventDefault();
      document.body.classList.remove('is-dragging');
      cell.classList.remove('drop-over');
      let payload;
      try { payload = JSON.parse(e.dataTransfer.getData('text/plain')); } catch { return; }
      if (!payload?.courseId) return;
      this.safe(() => Store.dropCourse(payload.courseId, cell.dataset.sem, cell.dataset.area, payload.fromArea || null));
    });
  }

  renderEmpty() {
    if (!Store.university()) {
      this.empty.innerHTML = 'No university yet. <button data-action="manage-universities" class="primary">Add a university</button>';
    } else {
      this.empty.innerHTML = `No course plan for ${Utils.esc(Store.university().universityName)}. <button data-action="new-plan" class="primary">Create a plan</button>`;
    }
  }

  render() {
    const plan = Store.plan();
    this.el.hidden = !plan;
    this.empty.hidden = !!plan;
    if (!plan) { this.renderEmpty(); return; }

    const showNames = !!Store.state.ui.showNames;
    this.refs.showNames.checked = showNames;
    const cols = Utils.planSemesters(plan);
    const issues = Validation.validate(plan);
    const credits = (e) => Store.course(e.courseId)?.credits || 0;

    const hue = (area) => (plan.areasOfStudy.indexOf(area) * 47) % 360;
    const rows = plan.areasOfStudy.map((a) => ({ key: a, label: a, hue: hue(a) }));
    const validAreas = (e) => e.areas.filter((a) => plan.areasOfStudy.includes(a));
    // Each course is displayed once, in the row of its primary (first) area.
    const displayRow = (e) => validAreas(e)[0] || UNASSIGNED;
    if (plan.courseList.some((e) => displayRow(e) === UNASSIGNED)) {
      rows.push({ key: UNASSIGNED, label: 'Unassigned', special: true, hue: 0 });
    }
    const countsToward = (e, key) => (key === UNASSIGNED ? displayRow(e) === UNASSIGNED : e.areas.includes(key));

    let highlight = Store.state.ui.highlightArea || null;
    if (highlight && !rows.some((r) => r.key === highlight)) highlight = null;

    const semTotal = (sem) => plan.courseList.filter((e) => e.semester === sem).reduce((s, e) => s + credits(e), 0);
    const rowTotal = (key) => plan.courseList.filter((e) => countsToward(e, key)).reduce((s, e) => s + credits(e), 0);
    const sharedIn = (key) => plan.courseList.filter((e) => countsToward(e, key) && displayRow(e) !== key).length;
    const grand = plan.courseList.reduce((s, e) => s + credits(e), 0);
    const fc = Utils.formatCredits;

    const chip = (e) => {
      const c = Store.course(e.courseId);
      const msgs = issues.get(e.courseId) || [];
      const areas = validAreas(e);
      const others = areas.slice(1);
      const tip = [
        `${e.courseId}${c ? ` — ${c.name}` : ''}`,
        c ? `${fc(c.credits)} credits` : '',
        areas.length ? `Areas: ${areas.join(', ')}` : 'No area of study assigned',
        c?.prerequisites?.length ? `Prereqs: ${Utils.formatReqInline(c.prerequisites)}` : '',
        c?.corequisites?.length ? `Coreqs: ${Utils.formatReqInline(c.corequisites)}` : '',
        ...msgs.map((m) => `⚠ ${m}`),
      ].filter(Boolean).join('\n');
      return `
        <div class="chip ${msgs.length ? 'chip-warn' : ''} ${c ? '' : 'chip-unknown'}" draggable="true"
             data-action="edit-chip" data-course="${Utils.esc(e.courseId)}" data-area="${Utils.esc(displayRow(e))}" title="${Utils.esc(tip)}">
          <span class="chip-main">
            ${msgs.length ? '<span class="chip-icon">⚠</span>' : ''}
            <span class="chip-id">${Utils.esc(e.courseId)}</span>
            <span class="chip-cr">${c ? fc(c.credits) : '?'}</span>
          </span>
          ${others.length ? `<span class="chip-areas">${others.map((a) => `<span class="chip-area" style="--area-hue:${hue(a)}">${Utils.esc(a)}</span>`).join('')}</span>` : ''}
          ${showNames && c ? `<span class="chip-name">${Utils.esc(c.name)}</span>` : ''}
          <button class="chip-x" data-action="remove-chip" title="Remove from plan">×</button>
        </div>`;
    };

    const issueCount = issues.size;
    this.refs.stats.innerHTML = `
      <span class="pg-stat"><b>${fc(grand)}</b> total credits</span>
      <span class="pg-stat"><b>${plan.courseList.length}</b> courses</span>
      ${issueCount ? `<span class="pg-stat pg-stat-warn">⚠ <b>${issueCount}</b> requisite issue${issueCount > 1 ? 's' : ''}</span>` : '<span class="pg-stat pg-stat-ok">✓ requisites satisfied</span>'}`;

    const head = `
      <thead><tr>
        <th class="pg-corner"><div>Area of study</div><div class="pg-grand">${fc(grand)} cr</div></th>
        ${cols.map((c) => `
          <th class="pg-sem ${c.key === PRE_COLLEGE ? 'pg-pre' : ''} ${c.term ? `term-${c.term.toLowerCase()}` : ''} ${c.extra ? 'pg-extra' : ''}"
              ${c.extra ? 'title="Outside the configured semesters (or hidden term) but contains courses"' : ''}>
            <div class="pg-sem-label">${Utils.esc(c.label)}</div>
            <div class="pg-sem-total">${fc(semTotal(c.key))} cr</div>
          </th>`).join('')}
      </tr></thead>`;

    const body = rows.map((r) => {
      const shared = sharedIn(r.key);
      return `
      <tr class="${r.special ? 'pg-row-special' : ''}" style="--row-hue:${r.hue}">
        <th class="pg-area">
          <button class="pg-area-btn" data-action="highlight-area" data-area="${Utils.esc(r.key)}" aria-pressed="false">
            <span class="pg-area-icon">○</span>
            <span class="pg-area-name">${Utils.esc(r.label)}</span>
          </button>
          <span class="pg-area-total" title="${shared ? `Includes ${shared} course(s) displayed in another row` : ''}">${fc(rowTotal(r.key))}${shared ? '<sup>*</sup>' : ''}</span>
        </th>
        ${cols.map((c) => {
          const entries = plan.courseList.filter((e) => e.semester === c.key && displayRow(e) === r.key);
          return `<td class="pg-cell ${c.key === PRE_COLLEGE ? 'pg-pre' : ''}" data-sem="${Utils.esc(c.key)}" data-area="${Utils.esc(r.key)}">
            ${entries.map((e) => chip(e)).join('')}
            <button class="pg-cell-add" data-action="add-in-cell" title="Add a course to ${Utils.esc(r.label)} · ${Utils.esc(c.label)}">+</button>
          </td>`;
        }).join('')}
      </tr>`;
    }).join('');

    const hlCount = highlight ? plan.courseList.filter((e) => countsToward(e, highlight)).length : 0;
    this.refs.highlight.hidden = !highlight;
    this.refs.highlight.innerHTML = highlight
      ? `Highlighting <b>${Utils.esc(highlight === UNASSIGNED ? 'Unassigned' : highlight)}</b>: ${hlCount} course(s), ${fc(rowTotal(highlight))} cr
         <button class="icon" data-action="clear-highlight" title="Clear highlight (Esc)">✕</button>`
      : '';

    const markup = head + `<tbody>${body || `<tr><td class="muted" colspan="${cols.length + 1}">Add areas of study in Plan settings.</td></tr>`}</tbody>`;
    // Keep the existing cells when only the selected area changes.
    if (this.tableMarkup !== markup) {
      this.refs.table.innerHTML = markup;
      this.tableMarkup = markup;
    }

    const entries = new Map(plan.courseList.map((e) => [e.courseId, e]));
    this.refs.table.querySelectorAll('.chip').forEach((el) => {
      const matches = !!highlight && countsToward(entries.get(el.dataset.course), highlight);
      el.classList.toggle('chip-hl', matches);
      el.classList.toggle('chip-dim', !!highlight && !matches);
    });
    this.refs.table.querySelectorAll('.pg-area-btn').forEach((button) => {
      const active = button.dataset.area === highlight;
      const label = button.querySelector('.pg-area-name').textContent;
      button.setAttribute('aria-pressed', String(active));
      button.title = active ? 'Clear highlight' : `Highlight all courses counting toward ${label}`;
      button.querySelector('.pg-area-icon').textContent = active ? '◉' : '○';
      button.closest('tr').classList.toggle('pg-row-hl', active);
    });
  }
};

/* ---- src/components/plan-settings/plan-settings.js ---- */
/* Collapsible configuration panel for the current plan. */
window.Components['plan-settings'] = class PlanSettings {
  constructor(host) {
    this.el = Utils.template('plan-settings');
    host.replaceWith(this.el);
    this.refs = Utils.refs(this.el);

    this.el.addEventListener('toggle', () => {
      if (Store.state.ui.settingsOpen !== this.el.open) Store.setUi({ settingsOpen: this.el.open });
    });
    this.el.querySelector('.ps-section').addEventListener('change', (e) => this.onFieldChange(e.target));
    this.refs.addForm.addEventListener('submit', (e) => {
      e.preventDefault();
      this.safe(() => Store.addArea(this.refs.newArea.value));
      this.refs.newArea.value = '';
      this.refs.newArea.focus();
    });
    this.refs.areas.addEventListener('change', (e) => {
      if (e.target.matches('input[data-area]')) {
        const ok = this.safe(() => Store.renameArea(e.target.dataset.area, e.target.value));
        if (!ok) e.target.value = e.target.dataset.area;
      }
    });
    this.refs.areas.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-action]');
      if (!btn) return;
      const area = btn.closest('li').dataset.area;
      if (btn.dataset.action === 'up') Store.moveArea(area, -1);
      if (btn.dataset.action === 'down') Store.moveArea(area, 1);
      if (btn.dataset.action === 'delete') {
        const used = Store.plan().courseList.filter((x) => x.areas.includes(area)).length;
        const msg = used ? `Delete area "${area}"? ${used} course(s) will lose this area.` : `Delete area "${area}"?`;
        if (confirm(msg)) Store.deleteArea(area);
      }
    });
  }

  safe(fn) {
    try { fn(); return true; } catch (err) { Utils.toast(err.message, 'error'); return false; }
  }

  onFieldChange(input) {
    const field = input.dataset.field;
    if (!field) return;
    const p = Store.plan();
    const start = Utils.parseSemester(p.startSemester) || { term: 'Fall', year: new Date().getFullYear() };
    switch (field) {
      case 'planName': Store.updatePlan({ planName: input.value.trim() || p.planName }); break;
      case 'startTerm': Store.updatePlan({ startSemester: `${input.value} ${start.year}` }); break;
      case 'startYear': {
        const y = parseInt(input.value, 10);
        if (y >= 1900 && y <= 2200) Store.updatePlan({ startSemester: `${start.term} ${y}` });
        else this.render();
        break;
      }
      case 'years': {
        const n = parseInt(input.value, 10);
        if (n >= 1 && n <= 10) Store.updatePlan({ years: n });
        else this.render();
        break;
      }
      case 'showWinter': Store.updatePlan({ showWinter: input.checked }); break;
      case 'showSummer': Store.updatePlan({ showSummer: input.checked }); break;
      default: break;
    }
  }

  render() {
    const p = Store.plan();
    this.el.hidden = !p;
    if (!p) return;
    this.el.open = !!Store.state.ui.settingsOpen;
    const r = this.refs;
    const start = Utils.parseSemester(p.startSemester) || { term: 'Fall', year: new Date().getFullYear() };
    const setVal = (el, v) => { if (document.activeElement !== el) el.value = v; };
    setVal(r.planName, p.planName);
    setVal(r.startTerm, start.term);
    setVal(r.startYear, start.year);
    setVal(r.years, p.years);
    r.showWinter.checked = p.showWinter;
    r.showSummer.checked = p.showSummer;

    const terms = ['Fall', 'Spring', p.showWinter && 'Winter', p.showSummer && 'Summer'].filter(Boolean).join(', ');
    r.summary.textContent = `${p.planName} · starts ${p.startSemester} · ${p.years} yr · ${terms} · ${p.areasOfStudy.length} areas`;

    r.areas.innerHTML = p.areasOfStudy.map((a, i) => `
      <li data-area="${Utils.esc(a)}">
        <input data-area="${Utils.esc(a)}" value="${Utils.esc(a)}" title="Rename area">
        <button type="button" class="icon" data-action="up" title="Move up" ${i === 0 ? 'disabled' : ''}>↑</button>
        <button type="button" class="icon" data-action="down" title="Move down" ${i === p.areasOfStudy.length - 1 ? 'disabled' : ''}>↓</button>
        <button type="button" class="icon" data-action="delete" title="Delete area">✕</button>
      </li>`).join('') || '<li class="muted">No areas yet — add one below.</li>';
  }
};

/* ---- src/components/university-manager/university-manager.js ---- */
/* Modal for adding / editing / deleting universities. */
window.Components['university-manager'] = class UniversityManager {
  constructor(host) {
    this.el = Utils.template('university-manager');
    host.replaceWith(this.el);
    this.refs = Utils.refs(this.el);
    this.editingId = null;

    Bus.on('manage-universities', () => this.open());
    this.refs.form.addEventListener('submit', (e) => { e.preventDefault(); this.save(); });
    this.el.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-action]');
      if (!btn) return;
      const id = btn.closest('tr')?.dataset.id;
      switch (btn.dataset.action) {
        case 'close': this.el.close(); break;
        case 'reset-form': this.resetForm(); break;
        case 'select': Store.selectUniversity(id); this.el.close(); break;
        case 'edit': this.startEdit(id); break;
        case 'delete': this.remove(id); break;
        default: break;
      }
    });
  }

  open() {
    this.resetForm();
    this.render();
    this.el.showModal();
  }

  resetForm() {
    this.editingId = null;
    const r = this.refs;
    r.id.value = '';
    r.name.value = '';
    r.error.textContent = '';
    r.formTitle.textContent = 'Add university';
    r.submit.textContent = 'Add university';
    r.cancelEdit.hidden = true;
  }

  startEdit(id) {
    const u = Store.university(id);
    if (!u) return;
    this.editingId = id;
    const r = this.refs;
    r.id.value = u.universityId;
    r.name.value = u.universityName;
    r.error.textContent = '';
    r.formTitle.textContent = `Edit ${u.universityName}`;
    r.submit.textContent = 'Save changes';
    r.cancelEdit.hidden = false;
    r.name.focus();
  }

  save() {
    try {
      Store.saveUniversity({ universityId: this.refs.id.value, universityName: this.refs.name.value }, this.editingId);
      Utils.toast(this.editingId ? 'University updated' : 'University added', 'success');
      this.resetForm();
    } catch (err) {
      this.refs.error.textContent = err.message;
    }
  }

  remove(id) {
    const u = Store.university(id);
    const plans = Store.plansForUniversity(id).length;
    if (confirm(`Delete ${u.universityName}? This also deletes its ${u.courses.length} roster course(s) and ${plans} plan(s).`)) {
      Store.deleteUniversity(id);
      if (this.editingId === id) this.resetForm();
    }
  }

  render() {
    const { state } = Store;
    this.refs.list.innerHTML = state.universities.map((u) => `
      <tr data-id="${Utils.esc(u.universityId)}" class="${u.universityId === state.ui.universityId ? 'um-current' : ''}">
        <td>${Utils.esc(u.universityName)}</td>
        <td><code>${Utils.esc(u.universityId)}</code></td>
        <td>${u.courses.length}</td>
        <td>${Store.plansForUniversity(u.universityId).length}</td>
        <td class="um-actions">
          <button class="icon" data-action="select" title="Open">Open</button>
          <button class="icon" data-action="edit" title="Edit">✎</button>
          <button class="icon" data-action="delete" title="Delete">🗑</button>
        </td>
      </tr>`).join('') || '<tr><td colspan="5" class="muted">No universities yet.</td></tr>';
  }
};

/* ---- src/app.js ---- */
/*
 * Boots the app: loads state, mounts every component registered on window.Components
 * into its matching [data-component] element, and re-renders on state changes.
 */
document.addEventListener('DOMContentLoaded', () => {
  Store.load();
  const instances = [];
  document.querySelectorAll('[data-component]').forEach((host) => {
    const Component = window.Components[host.dataset.component];
    if (!Component) {
      console.warn(`No component registered for "${host.dataset.component}"`);
      return;
    }
    const instance = new Component(host);
    instances.push(instance);
  });
  const renderAll = () => instances.forEach((c) => c.render && c.render());
  Store.subscribe(renderAll);
  renderAll();
});
